function hexRgb(h){return parseInt(h.slice(1,3),16)+','+parseInt(h.slice(3,5),16)+','+parseInt(h.slice(5,7),16)}
function setAccent(hex){
  currentColor=hex;
  var r=document.documentElement;
  r.style.setProperty('--acc',hex);
  r.style.setProperty('--acc-rgb',hexRgb(hex));
}

function statLevel(v){
  if(v<100)return{en:'Sideshow',color:'#786050',desc:'Barely worth a ticket stub'};
  if(v<300)return{en:'Understudy',color:'#9A8060',desc:'Still learning the ropes'};
  if(v<500)return{en:'Featured Act',color:'#B09040',desc:'Draws a modest crowd'};
  if(v<700)return{en:'Headliner',color:'#C9922A',desc:'Top of the marquee'};
  if(v<850)return{en:'Star of the Show',color:'#D4708A',desc:'The reason people come'};
  if(v<980)return{en:'Legend of the Big Top',color:'#8A6ACE',desc:'Whispered about in every troupe'};
  if(v<1000)return{en:'Otherworldly',color:'#8B1A2B',desc:'Something more than human skill'};
  return{en:'Beyond the Veil',color:'#FFD700',desc:'Touches what should not be touched'};
}

function renderStats(){
  var wrap=g('stats-wrap');if(!wrap)return;
  var h='';
  STATS.forEach(function(s){
    var v=statVals[s.id]!=null?statVals[s.id]:200;
    statVals[s.id]=v;
    var lv=statLevel(v);
    h+='<div class="stat-block">'+
      '<div class="stat-top"><div><div class="stat-nm">'+s.nm+'</div><div class="stat-desc">'+s.desc+'</div></div>'+
      '<span class="stat-badge" id="stat-badge-'+s.id+'" style="background:'+lv.color+'22;color:'+lv.color+';border:1px solid '+lv.color+'55">'+lv.en+'</span></div>'+
      '<input type="range" min="0" max="1000" value="'+v+'" id="stat-'+s.id+'">'+
    '</div>';
  });
  wrap.innerHTML=h;
  STATS.forEach(function(s){
    var inp=g('stat-'+s.id);
    if(inp)inp.addEventListener('input',function(){updateStat(s.id,parseInt(this.value))});
  });
}
function updateStat(id,v){
  statVals[id]=v;
  var lv=statLevel(v);
  var b=g('stat-badge-'+id);
  if(b){b.textContent=lv.en;b.style.background=lv.color+'22';b.style.color=lv.color;b.style.border='1px solid '+lv.color+'55'}
}

function renderTctTabs(){
  var row=g('tct-row');if(!row)return;
  row.innerHTML=TRAIT_CATS.map(function(c){
    return '<div class="tct'+(c.id===curTctCat?' active':'')+'" data-cat="'+c.id+'">'+c.label+'</div>';
  }).join('');
  renderTraits();
}
function renderTraits(){
  var grid=g('trait-grid');if(!grid)return;
  var cat=TRAIT_CATS.find(function(c){return c.id===curTctCat});
  if(!cat)return;
  grid.innerHTML=cat.traits.map(function(t){
    return '<div class="trait-chip'+(selTraits.indexOf(t.n)>=0?' on':'')+'" data-n="'+esc(t.n)+'" data-d="'+esc(t.d)+'">'+t.n+'</div>';
  }).join('');
}

