function goTab(n){
  n=Math.max(0,Math.min(4,n));
  curTab=n;
  document.querySelectorAll('.mn-tab').forEach(function(t){t.classList.toggle('on',parseInt(t.dataset.t)===n)});
  document.querySelectorAll('.mn-pane').forEach(function(p){p.classList.toggle('on',parseInt(p.dataset.p)===n)});
  document.querySelectorAll('.mn-dot').forEach(function(d,i){d.classList.toggle('on',i===n)});
  g('mn-prev').disabled=(n===0);
  g('mn-next').style.display=(n===4)?'none':'inline-block';
  g('mn-submit').style.display=(n===4)?'inline-block':'none';
}

document.querySelectorAll('.mn-tab').forEach(function(t){t.addEventListener('click',function(){goTab(parseInt(this.dataset.t))})});
